// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List contributors awaiting approval (super admin only)
	// (GET /admin/contributors/pending)
	ListPendingContributors(ctx context.Context, request ListPendingContributorsRequestObject) (ListPendingContributorsResponseObject, error)
	// Approve a pending contributor (super admin only)
	// (POST /admin/contributors/{userId}/approve)
	ApproveContributor(ctx context.Context, request ApproveContributorRequestObject) (ApproveContributorResponseObject, error)
	// Reject a pending contributor (super admin only)
	// (POST /admin/contributors/{userId}/reject)
	RejectContributor(ctx context.Context, request RejectContributorRequestObject) (RejectContributorResponseObject, error)
	// Get platform-wide statistics (super admin only)
	// (GET /admin/stats)
	GetAdminStats(ctx context.Context, request GetAdminStatsRequestObject) (GetAdminStatsResponseObject, error)
	// List all tests with attempt counts (super admin only)
	// (GET /admin/tests)
	ListAdminTests(ctx context.Context, request ListAdminTestsRequestObject) (ListAdminTestsResponseObject, error)
	// List all users with optional filters (super admin only)
	// (GET /admin/users)
	ListAdminUsers(ctx context.Context, request ListAdminUsersRequestObject) (ListAdminUsersResponseObject, error)
	// Update a user's account status (super admin only)
	// (PATCH /admin/users/{userId}/status)
	UpdateAdminUserStatus(ctx context.Context, request UpdateAdminUserStatusRequestObject) (UpdateAdminUserStatusResponseObject, error)
	// Authenticate and receive tokens
	// (POST /auth/login)
	PostAuthLogin(ctx context.Context, request PostAuthLoginRequestObject) (PostAuthLoginResponseObject, error)
	// Invalidate the current refresh token
	// (POST /auth/logout)
	PostAuthLogout(ctx context.Context, request PostAuthLogoutRequestObject) (PostAuthLogoutResponseObject, error)
	// Get the current authenticated user's profile
	// (GET /auth/me)
	GetAuthMe(ctx context.Context, request GetAuthMeRequestObject) (GetAuthMeResponseObject, error)
	// Rotate refresh token and get a new access token
	// (POST /auth/refresh)
	PostAuthRefresh(ctx context.Context, request PostAuthRefreshRequestObject) (PostAuthRefreshResponseObject, error)
	// Register a new user
	// (POST /auth/register)
	PostAuthRegister(ctx context.Context, request PostAuthRegisterRequestObject) (PostAuthRegisterResponseObject, error)
	// Health check
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// Get top-100 leaderboard
	// (GET /leaderboard)
	GetLeaderboard(ctx context.Context, request GetLeaderboardRequestObject) (GetLeaderboardResponseObject, error)
	// Get the caller's personal rank on the leaderboard (student only)
	// (GET /leaderboard/me)
	GetLeaderboardMe(ctx context.Context, request GetLeaderboardMeRequestObject) (GetLeaderboardMeResponseObject, error)
	// List questions (contributor/admin)
	// (GET /questions)
	GetQuestions(ctx context.Context, request GetQuestionsRequestObject) (GetQuestionsResponseObject, error)
	// Create a question (contributor only)
	// (POST /questions)
	PostQuestions(ctx context.Context, request PostQuestionsRequestObject) (PostQuestionsResponseObject, error)
	// Delete a question (own only; blocked if in published test)
	// (DELETE /questions/{questionId})
	DeleteQuestionsQuestionId(ctx context.Context, request DeleteQuestionsQuestionIdRequestObject) (DeleteQuestionsQuestionIdResponseObject, error)
	// Get question detail
	// (GET /questions/{questionId})
	GetQuestionsQuestionId(ctx context.Context, request GetQuestionsQuestionIdRequestObject) (GetQuestionsQuestionIdResponseObject, error)
	// Update a question (own only for contributor, any for admin)
	// (PATCH /questions/{questionId})
	PatchQuestionsQuestionId(ctx context.Context, request PatchQuestionsQuestionIdRequestObject) (PatchQuestionsQuestionIdResponseObject, error)
	// List results (own for student, all for admin)
	// (GET /results)
	GetResults(ctx context.Context, request GetResultsRequestObject) (GetResultsResponseObject, error)
	// Get result detail with per-topic breakdown
	// (GET /results/{resultId})
	GetResultsResultId(ctx context.Context, request GetResultsResultIdRequestObject) (GetResultsResultIdResponseObject, error)
	// Per-question review with correct answers and explanations
	// (GET /results/{resultId}/review)
	GetResultsResultIdReview(ctx context.Context, request GetResultsResultIdReviewRequestObject) (GetResultsResultIdReviewResponseObject, error)
	// Get session state (with current answers and time remaining)
	// (GET /sessions/{sessionId})
	GetSessionsSessionId(ctx context.Context, request GetSessionsSessionIdRequestObject) (GetSessionsSessionIdResponseObject, error)
	// Save or update an answer (blank if selected_option_id omitted)
	// (POST /sessions/{sessionId}/answers)
	PostSessionsSessionIdAnswers(ctx context.Context, request PostSessionsSessionIdAnswersRequestObject) (PostSessionsSessionIdAnswersResponseObject, error)
	// Toggle flag on a question
	// (POST /sessions/{sessionId}/flag)
	PostSessionsSessionIdFlag(ctx context.Context, request PostSessionsSessionIdFlagRequestObject) (PostSessionsSessionIdFlagResponseObject, error)
	// Submit the session and compute the result
	// (POST /sessions/{sessionId}/submit)
	PostSessionsSessionIdSubmit(ctx context.Context, request PostSessionsSessionIdSubmitRequestObject) (PostSessionsSessionIdSubmitResponseObject, error)
	// List tests
	// (GET /tests)
	GetTests(ctx context.Context, request GetTestsRequestObject) (GetTestsResponseObject, error)
	// Create a new test (contributor/admin)
	// (POST /tests)
	PostTests(ctx context.Context, request PostTestsRequestObject) (PostTestsResponseObject, error)
	// Delete test (contributor/admin, draft only)
	// (DELETE /tests/{testId})
	DeleteTestsTestId(ctx context.Context, request DeleteTestsTestIdRequestObject) (DeleteTestsTestIdResponseObject, error)
	// Get test by ID
	// (GET /tests/{testId})
	GetTestsTestId(ctx context.Context, request GetTestsTestIdRequestObject) (GetTestsTestIdResponseObject, error)
	// Update test metadata (contributor/admin, draft only)
	// (PATCH /tests/{testId})
	PatchTestsTestId(ctx context.Context, request PatchTestsTestIdRequestObject) (PatchTestsTestIdResponseObject, error)
	// Publish a draft test (contributor/admin)
	// (POST /tests/{testId}/publish)
	PostTestsTestIdPublish(ctx context.Context, request PostTestsTestIdPublishRequestObject) (PostTestsTestIdPublishResponseObject, error)
	// Replace all questions in a test (contributor/admin, draft only)
	// (PUT /tests/{testId}/questions)
	PutTestsTestIdQuestions(ctx context.Context, request PutTestsTestIdQuestionsRequestObject) (PutTestsTestIdQuestionsResponseObject, error)
	// Update scoring config (contributor/admin, draft only)
	// (PATCH /tests/{testId}/scoring)
	PatchTestsTestIdScoring(ctx context.Context, request PatchTestsTestIdScoringRequestObject) (PatchTestsTestIdScoringResponseObject, error)
	// Start a new test session (or resume existing in-progress session)
	// (POST /tests/{testId}/sessions)
	PostTestsTestIdSessions(ctx context.Context, request PostTestsTestIdSessionsRequestObject) (PostTestsTestIdSessionsResponseObject, error)
	// Unpublish a test back to draft (admin only)
	// (POST /tests/{testId}/unpublish)
	PostTestsTestIdUnpublish(ctx context.Context, request PostTestsTestIdUnpublishRequestObject) (PostTestsTestIdUnpublishResponseObject, error)
	// List all topics
	// (GET /topics)
	GetTopics(ctx context.Context, request GetTopicsRequestObject) (GetTopicsResponseObject, error)
	// Create a topic (admin only)
	// (POST /topics)
	PostTopics(ctx context.Context, request PostTopicsRequestObject) (PostTopicsResponseObject, error)
	// Delete a topic (admin only)
	// (DELETE /topics/{topicId})
	DeleteTopicsTopicId(ctx context.Context, request DeleteTopicsTopicIdRequestObject) (DeleteTopicsTopicIdResponseObject, error)
	// Update a topic (admin only)
	// (PATCH /topics/{topicId})
	PatchTopicsTopicId(ctx context.Context, request PatchTopicsTopicIdRequestObject) (PatchTopicsTopicIdResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

